mapper.update:
update sys_message  set updated_by = #{updatedBy} , updated_dt = #{updatedDt}

    , type = #{type}


    , title = #{title}


    , content = #{content}

where id = #{id}

mapper.select:
select from sys_message where 1 = 1
order by id desc
limit #{startRow}, #{pageSize}

mapper.sql:
and mu.user_id = #{userId}

    and m.type = #{type}


    and m.title like concat('%', #{title}, '%')


    and m.tenant_id = #{tenantId}

and m.delete_flag = 1
and mu.delete_flag = 1

mapper.select:
select m.id , m.tenant_id, m.type , m.title , m.content , m.ref_id, m.delete_flag , m.created_by , m.created_dt , m.updated_by , m.updated_dt from sys_message_user mu inner join sys_message m on mu.msg_id = m.id where 1 = 1
order by m.created_dt desc , m.id desc
limit #{startRow}, #{pageSize}
